SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "契丹乘新州之胜围幽州。", "citation": "卷269·贞明三年（917）·zztj-v269-y0917-p007·原文件第111行", "note": "原文：契丹乘胜进围幽州，声言有众百万，氈车毳幕弥温山泽。；核对说明：百万为契丹声称之数，不作实际兵力；氈字保留底本字形。", "status": "draft", "id": "9c956735-5edf-513e-bbb3-ab108f0b068d", "subject_id": "71d1a8fd-6df6-5eaa-af7f-d85b440f83a0", "source_id": "8682fd91-f816-5b4e-b7b4-6f40e42c56ec"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "917年三月至四月间；围城确日未载", "citation": "卷269·贞明三年（917）·zztj-v269-y0917-p007·原文件第111行", "note": "原文：契丹乘胜进围幽州，声言有众百万，氈车毳幕弥温山泽。；核对说明：只保留原纪年，不换算公历日；叙述性回顾不推成逐次日期。", "status": "draft", "id": "d3119d36-1dde-567d-a33f-b5323edc4171", "subject_id": "71d1a8fd-6df6-5eaa-af7f-d85b440f83a0", "source_id": "8682fd91-f816-5b4e-b7b4-6f40e42c56ec"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》也记契丹乘胜攻幽州，并述同时有五十万与百万两种传闻。", "citation": "《旧五代史》卷二十八，段落 jiu-wudaishi-205deb4a7860-p000934；EPUB电子本，纸本及异文待核", "note": "原文：契丹乘勝寇幽州。是時言契丹者，或云五十萬，或云百萬；核对说明：人数为当时传闻，不能视作确数。", "status": "draft", "id": "36fb4198-5940-57fa-8cd3-3f6134190e20", "subject_id": "71d1a8fd-6df6-5eaa-af7f-d85b440f83a0", "source_id": "07afa5ce-dee3-559f-97ba-197a23ee9b19"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "《辽史》太祖纪系围幽州于神册二年四月。", "citation": "《辽史》卷一，段落 liaoshi-7cd182a20e67-p000221；EPUB电子本，纸本及异文待核", "note": "原文：夏四月壬午，圍幽州，不克。；核对说明：与主书段落衔接的三月至四月时间并列保留。", "status": "draft", "id": "4315b6c3-cf10-5252-9bd0-cdbe97942bad", "subject_id": "71d1a8fd-6df6-5eaa-af7f-d85b440f83a0", "source_id": "87d102e6-e32c-53ce-8f4d-6bd938e03e9e"}, {"subject_table": "event", "field_path": "description", "claim_text": "卢文进教契丹作地道与土山围攻幽州。", "citation": "卷269·贞明三年（917）·zztj-v269-y0917-p007·原文件第111行", "note": "原文：卢文进教之攻城，为地道，昼夜四面俱进，城中穴地然膏以邀之。又为土山以临城，城中熔铜以洒之，日杀千计，而攻之不止。；核对说明：“日杀千计”为主书记述，未另核算杀伤；城中抵御方法亦按原文。", "status": "draft", "id": "467dca58-7173-5f52-813f-6e5b4abe3562", "subject_id": "7f673a5c-2be7-59bb-8100-138eefc6259d", "source_id": "8682fd91-f816-5b4e-b7b4-6f40e42c56ec"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "917年本段条；确日未载", "citation": "卷269·贞明三年（917）·zztj-v269-y0917-p007·原文件第111行", "note": "原文：卢文进教之攻城，为地道，昼夜四面俱进，城中穴地然膏以邀之。又为土山以临城，城中熔铜以洒之，日杀千计，而攻之不止。；核对说明：只保留原纪年，不换算公历日；叙述性回顾不推成逐次日期。", "status": "draft", "id": "82726546-890d-5ea2-a014-875dd2d33c67", "subject_id": "7f673a5c-2be7-59bb-8100-138eefc6259d", "source_id": "8682fd91-f816-5b4e-b7b4-6f40e42c56ec"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记卢文进：教授契丹攻城法者。", "citation": "卷269·贞明三年（917）·zztj-v269-y0917-p007·原文件第111行", "note": "原文：卢文进教之攻城，为地道，昼夜四面俱进，城中穴地然膏以邀之。又为土山以临城，城中熔铜以洒之，日杀千计，而攻之不止。；核对说明：原文称谓与既有姓名合并；原文摘录保留底本字形。", "status": "draft", "id": "7925f08e-63d6-5ce7-8b5a-d6ebdc9e4cd8", "subject_id": "ead2e914-83dd-5f41-bf9a-5956fbd149ab", "source_id": "8682fd91-f816-5b4e-b7b4-6f40e42c56ec"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "卢文进：教授契丹攻城法者。", "citation": "卷269·贞明三年（917）·zztj-v269-y0917-p007·原文件第111行", "note": "原文：卢文进教之攻城，为地道，昼夜四面俱进，城中穴地然膏以邀之。又为土山以临城，城中熔铜以洒之，日杀千计，而攻之不止。；核对说明：参与身份依据本句；称谓按既有主体匹配。", "status": "draft", "id": "e4f179fe-8c6e-5733-8354-f53470f62227", "subject_id": "c133def2-d2f4-5aef-96d0-05000eb2a502", "source_id": "8682fd91-f816-5b4e-b7b4-6f40e42c56ec"}, {"subject_table": "event", "field_path": "description", "claim_text": "周德威遣密使向晋王求援。", "citation": "卷269·贞明三年（917）·zztj-v269-y0917-p007·原文件第111行", "note": "原文：周德威遣间使诣晋王告急，王方与梁相持河上，欲分兵则兵少，欲勿救恐失之，忧形于色，谋于诸将，独李嗣源、李存审、阎宝劝王救之。；核对说明：李存审、阎宝主张等待契丹粮尽后追击，李嗣源主张立即赴援；同赞成救援但方案不同。", "status": "draft", "id": "f4efedcd-bd4b-5a61-9636-93f1685179a0", "subject_id": "6aeb1880-db79-59a8-ab4a-261e832e6c97", "source_id": "8682fd91-f816-5b4e-b7b4-6f40e42c56ec"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "917年本段条；确日未载", "citation": "卷269·贞明三年（